let xlState=null,xlBatch=null,xlError='',xlBusy=false,xlLoaded=false,xlBranch='TAI SIAM Tachileik',xlFrom='',xlTo='',xlChoices={},xlView='ledger';
const xlOldReports=reportsPage,xlOldImport=importPage;
async function xlApi(path,body){let r=await fetch('/api/excel'+path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});if(!r.ok){let e=await r.json().catch(()=>({error:'ยังเชื่อมต่อระบบบัญชีไม่ได้ หากเปิดเว็บบน Cloudflare ต้องติดตั้ง backend บัญชีก่อน'}));throw new Error(e.error)}return r.json()}
async function xlLoad(){try{xlState=await xlApi('/state');xlError='';xlLoaded=true}catch(e){xlError=e.message;xlLoaded=true}if(['reports','import'].includes(route))render()}
function xlChoice(g){return xlChoices[g.sourceRow]??=( {date:g.date||'',note:'',selected:false,action:'create',existingId:null})}
function xlOld(g){let c=xlChoice(g),b=g.branch||xlBranch;return xlState?.records.find(r=>g.recordId?r.id===g.recordId:r.source.batchId===xlBatch.id&&r.source.row===g.sourceRow)||xlState?.records.find(r=>r.branch===b&&r.date===c.date)}
const xlKeys=['pump','fuel','opening','closing','liters','cost','price','received','discount','credit','debtPaid','legacyR','legacyV','legacyW'];
function xlSame(g,old){return old&&old.date===xlChoice(g).date&&JSON.stringify(g.lines.map(l=>xlKeys.map(k=>l[k]??null)))===JSON.stringify(old.lines.map(l=>xlKeys.map(k=>l[k]??null)))}
function xlList(){return (xlState?.records||[]).filter(r=>(!xlBranch||r.branch===xlBranch)&&(!xlFrom||r.date>=xlFrom)&&(!xlTo||r.date<=xlTo))}
function xlLayout(title,sub,body){return head(title,sub)+`<div class="note">ข้อมูล Excel จริงบันทึกอยู่ในเครื่องนี้ เปิดใหม่ข้อมูลยังอยู่ · ข้อมูลสาธิตในเมนูอื่นแยกต่างหาก</div><div class="tabs"><button class="${xlView==='ledger'?'selected':''}" onclick="xlView='ledger';go('reports')">สมุดบัญชีจริง</button><button class="${xlView==='files'?'selected':''}" onclick="xlView='files';go('reports')">ไฟล์และประวัติ</button><button onclick="go('import')">นำเข้า / เทียบ Excel</button></div>${xlError?`<div class="note error" role="alert">${esc(xlError)}</div>`:''}${body}`}
reportsPage=function(){if(!canAccount())return xlOldReports();if(!xlLoaded){if(!xlBusy){xlBusy=true;xlLoad().finally(()=>{xlBusy=false;render()})}return head('Excel และงานบัญชี','กำลังอ่านข้อมูลที่บันทึกในเครื่อง…')}let list=xlList();if(xlView==='files')return xlLayout('ไฟล์และประวัติ','ติดตามว่าแต่ละรายการมาจากไฟล์ไหน',`<section class="panel"><h2>ไฟล์ที่อ่านแล้ว</h2>${table(['ชื่อไฟล์','จำนวนบล็อกที่มีข้อมูล','ดำเนินการ'],(xlState?.batches||[]).map(b=>`<tr><td>${esc(b.filename)}</td><td>${b.groups}</td><td><button onclick="xlOpen('${b.id}')">ตรวจ / เปรียบเทียบ</button> <a href="/api/excel/source/${b.id}">ต้นฉบับ</a></td></tr>`))}</section><section class="panel"><h2>ประวัติข้อมูลจริง</h2>${table(['เวลา','การทำรายการ','รายละเอียด'],(xlState?.history||[]).map(h=>`<tr><td>${new Date(h.time).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'})}</td><td>${esc(h.action)}</td><td>${esc(h.detail)}</td></tr>`))}<a href="/api/excel/backup">ดาวน์โหลดสำรองข้อมูลบัญชี JSON</a></section>`);
return xlLayout('Excel และงานบัญชี','นำเข้า Excel เดิม หรือกรอกบนเว็บ แล้วส่งออกไปทำงานต่อ',`<div class="actions xl-actions"><button class="primary" onclick="go('import')">นำเข้า Excel</button><button onclick="xlManual()">+ บันทึกยอดขายจริง</button><button onclick="xlExport()" ${!list.length?'disabled':''}>ดาวน์โหลด Excel (.xlsx)</button><button onclick="xlLoad()">โหลดข้อมูลล่าสุด</button></div><div class="filters"><input aria-label="สาขาจริง" placeholder="ทุกสาขา" value="${esc(xlBranch)}" onchange="xlBranch=this.value;render()"><input type="date" aria-label="ตั้งแต่วันที่" value="${xlFrom}" onchange="xlFrom=this.value;render()"><input type="date" aria-label="ถึงวันที่" value="${xlTo}" onchange="xlTo=this.value;render()"></div><div class="summarygrid"><div class="summarycard bluecard"><div><span>ยอดขายก่อนส่วนลด / ขายเชื่อ</span><strong>${fmt(list.reduce((s,r)=>s+r.sales,0))}<small> บาท</small></strong><small>${list.length} วันตามตัวกรอง · ไม่ใช่เงินรับ</small></div></div><div class="summarycard"><div><span>ปริมาณขาย</span><strong>${fmt(list.reduce((s,r)=>s+r.liters,0))}<small> ลิตร</small></strong></div></div><div class="summarycard"><div><span>ไฟล์ที่รอตรวจ / เคยนำเข้า</span><strong>${xlState?.batches.length||0}<small> ไฟล์</small></strong><button onclick="xlView='files';render()">เปิดไฟล์</button></div></div></div><section class="panel">${table(['วันที่ / สาขา','ลิตรขาย','ยอดขายก่อนปรับ','สถานะ','รายละเอียด'],list.map(r=>`<tr><td>${esc(r.date)}<br>${esc(r.branch)}</td><td>${fmt(r.liters)}</td><td>${fmt(r.sales)}</td><td>${badge(esc(r.status))}</td><td><button onclick="xlDetail('${r.id}')">เปิดรายการ</button></td></tr>`))}${!list.length?'<div class="note">ยังไม่มีข้อมูลยืนยันในสมุดจริง เปิดไฟล์ excel-report.xlsx ใน “ไฟล์และประวัติ” เพื่อตรวจวันที่ก่อนนำเข้า</div>':''}</section><div class="note">ส่งออกแล้วแก้ช่องกรอกในชีต “รายการเว็บ” ได้ จากนั้นนำกลับมาตรวจค่าเดิม–ค่าใหม่ ไม่มีการซิงก์หรือเขียนทับอัตโนมัติ</div>`)};
async function xlOpen(id){xlError='';try{if(!xlState)await xlLoad();xlBatch=await xlApi('/batch/'+id);xlChoices={};go('import')}catch(e){xlError=e.message;render()}}
importPage=function(){if(!canAccount())return xlOldImport();if(!xlLoaded){if(!xlBusy){xlBusy=true;xlLoad().finally(()=>{xlBusy=false;render()})}return head('นำเข้า Excel','กำลังโหลด…')}if(!xlBatch)return xlLayout('นำเข้า Excel จริง','รองรับไฟล์บัญชีขายรายวันรูปแบบเดิม และไฟล์ที่เว็บส่งออก',`<section class="panel"><form onsubmit="event.preventDefault();xlUpload(this)"><div class="field"><label for="xlfile">เลือกไฟล์ .xlsx</label><input id="xlfile" name="file" type="file" accept=".xlsx" required></div><button class="primary" ${xlBusy?'disabled':''}>${xlBusy?'กำลังอ่านไฟล์…':'อ่านและตรวจตัวอย่าง'}</button></form><p class="muted">อ่านเฉพาะในเครื่องนี้ ยังไม่ลงสมุดบัญชีจนกว่าจะยืนยัน</p></section><section class="panel"><h2>ไฟล์ที่มีอยู่แล้ว</h2>${(xlState?.batches||[]).map(b=>`<div class="task"><div class="taskbody">${esc(b.filename)}<small>${b.groups} บล็อกที่มีข้อมูลจริง</small></div><button onclick="xlOpen('${b.id}')">เปิดตรวจ</button></div>`).join('')}</section>`);
let groups=xlBatch.groups;return xlLayout('ตรวจ Excel ก่อนบันทึก',esc(xlBatch.filename),`<div class="actions xl-actions"><button onclick="xlBatch=null;render()">เลือกไฟล์อื่น</button><button onclick="xlExport('${xlBatch.id}')">ดาวน์โหลดใบตรวจ Excel</button><a href="/api/excel/source/${xlBatch.id}">ดาวน์โหลดต้นฉบับเดิม</a></div><div class="formgrid"><div class="field"><label for="xlbranch">สาขาจริงของไฟล์</label><input id="xlbranch" value="${esc(xlBranch)}" onchange="xlBranch=this.value;render()" ${xlBatch.format==='web'?'disabled':''}></div><div class="note">${groups.length} บล็อก / ${groups.reduce((n,g)=>n+g.lines.length,0)} แถวที่มีข้อมูล · ข้าม ${xlBatch.emptyPumpRows} แถวหัวจ่ายที่ยังไม่ได้กรอก</div></div><details class="panel"><summary>สิ่งที่ตรวจพบและวิธีอ่านข้อมูล</summary><ul>${xlBatch.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul><p>ยอดขายรวมจากลิตร × ราคา ${fmt(groups.reduce((s,g)=>s+g.sales,0))} บาท${xlBatch.sourceSummary?.Q138!=null?' · ยอดใน Q138 เดิม '+fmt(xlBatch.sourceSummary.Q138)+' บาท':''}</p><p>วันที่ที่อ่านได้เป็นวันที่ที่เก็บอยู่ในไฟล์ ไม่สลับวัน/เดือนหรือแก้ปีให้อัตโนมัติ</p></details>${xlPreviewTable(groups)}`)};
function xlPreviewTable(groups){return `<section class="panel">${table(['เลือก','ต้นทาง / วันที่เดิม','วันที่ยืนยัน','ยอดขาย','ผลเทียบ','ตรวจและอธิบาย'],groups.map(g=>{let ch=xlChoice(g),old=xlOld(g),same=xlSame(g,old);return `<tr><td><input aria-label="เลือกแถว ${g.sourceRow}" type="checkbox" ${ch.selected?'checked':''} onchange="xlChoices[${g.sourceRow}].selected=this.checked"></td><td>${esc(xlBatch.sheet)}!A${g.sourceRow}<br><small>${esc(g.rawDate)}</small>${g.branch?'<br>'+esc(g.branch):''}</td><td><input aria-label="วันที่แถว ${g.sourceRow}" type="date" value="${esc(ch.date)}" onchange="xlChoices[${g.sourceRow}].date=this.value;render()"></td><td>${fmt(g.sales)}</td><td>${badge(old?same?'เหมือนเดิม':'มีค่าเปลี่ยน':'รายการใหม่')}<br><small>${g.issues.length} ข้อควรตรวจ</small></td><td><button onclick="xlCompare(${g.sourceRow})">ดูค่าเดิม–ค่าใหม่</button><input aria-label="หมายเหตุแถว ${g.sourceRow}" placeholder="เหตุผล / ยืนยันวันที่ตามเอกสาร" value="${esc(ch.note)}" oninput="xlChoices[${g.sourceRow}].note=this.value">${old?`<label class="checkrow"><input type="checkbox" ${ch.action==='update'?'checked':''} onchange="xlChoices[${g.sourceRow}].action=this.checked?'update':'create';xlChoices[${g.sourceRow}].existingId='${old.id}'">อัปเดตรายการเดิมนี้</label>`:''}</td></tr>`}))}</section><div class="footactions"><p>เฉพาะแถวที่เลือก · ยืนยันว่าตรวจวันที่และยอดขายแล้ว</p><button class="primary" onclick="xlCommit()" ${xlBusy?'disabled':''}>${xlBusy?'กำลังบันทึก…':'ยืนยันรายการที่เลือก'}</button></div>`}
async function xlUpload(form){let f=form.file.files[0];if(!f)return;xlBusy=true;xlError='';let button=form.querySelector('button');button.disabled=true;button.textContent='กำลังอ่านไฟล์…';try{let r=await fetch('/api/excel/import',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Filename':encodeURIComponent(f.name)},body:f});let b=await r.json();if(!r.ok)throw new Error(b.error);xlBatch=b;xlChoices={};await xlLoad()}catch(e){xlError=e.message}finally{xlBusy=false;render()}}
const xlNames={pump:'หัวจ่าย',fuel:'น้ำมัน',opening:'มิเตอร์เปิด',closing:'มิเตอร์ปิด',liters:'ลิตรขาย',cost:'ต้นทุน/ลิตร',price:'ราคาขาย/ลิตร',received:'รับเข้า (ลิตร)',discount:'ส่วนลด (บาท)',credit:'ขายเชื่อ (บาท)',debtPaid:'รับชำระหนี้ (บาท)',legacyR:'วัดจริง (ลิตร)',legacyV:'เกิน (ลิตร)',legacyW:'หาย (ลิตร)'};
function xlCompare(row){let g=xlBatch.groups.find(g=>g.sourceRow===row),old=xlOld(g),diff=[];g.lines.forEach((l,i)=>{let before=old?.lines.find(b=>String(b.lineId||b.row)===String(l.lineId||l.row));for(const key of xlKeys)if(!before||before[key]!==l[key])diff.push(`<tr><td>${esc(l.pump)} · แถว ${l.row}</td><td>${xlNames[key]}</td><td>${esc(before?.[key]??'—')}</td><td>${esc(l[key]??'—')}</td></tr>`)});if(old)for(const before of old.lines)if(!g.lines.some(l=>String(l.lineId||l.row)===String(before.lineId||before.row)))diff.push(`<tr><td>${esc(before.pump)}</td><td>แถวถูกนำออก</td><td>${fmt(before.liters)} ลิตร</td><td>ไม่มีใน Excel ชุดนี้</td></tr>`);modal('เปรียบเทียบข้อมูลก่อนนำเข้า',`<p>${esc(g.rawDate)} → ${esc(xlChoice(g).date||'ยังไม่ยืนยัน')} · ${old?'รายการเดิม '+old.date:'รายการใหม่'}</p>${g.issues.length?'<div class="note warning">'+g.issues.map(esc).join('<br>')+'</div>':''}${table(['หัวจ่าย / แถว','ช่องข้อมูล','ค่าเดิมในเว็บ','ค่าจาก Excel'],diff)}${old&&old.lines.length!==g.lines.length?'<div class="note warning">จำนวนแถวเปลี่ยน: '+old.lines.length+' → '+g.lines.length+' โปรดตรวจการแยกต้นทุน</div>':''}<div class="note">ยอดวัดจริงและเกิน/หายเป็นลิตร ไม่หักออกจากเงินขาย ไม่มีการคำนวณกำไรสุทธิจากสูตรเก่า</div>`)}
async function xlCommit(){let entries=xlBatch.groups.filter(g=>xlChoice(g).selected).map(g=>({sourceRow:g.sourceRow,...xlChoice(g),confirmed:true}));if(!entries.length)return toast('เลือกอย่างน้อยหนึ่งวันก่อน');if(entries.some(e=>!e.date||!e.note.trim()))return toast('กรุณาระบุวันที่และหมายเหตุสำหรับทุกวันที่เลือก');xlBusy=true;xlError='';render();try{let result=await xlApi('/commit',{batchId:xlBatch.id,branch:xlBranch,revision:xlState.revision,entries});await xlLoad();xlBatch=null;xlChoices={};xlView='ledger';go('reports');toast('บันทึกข้อมูลจริง '+result.count+' วันแล้ว')}catch(e){xlError=e.message;await xlLoad().catch(()=>{});xlError=e.message}finally{xlBusy=false;render()}}
async function xlExport(batchId){toast('กำลังสร้าง Excel…');try{let r=await fetch('/api/excel/export',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(batchId?{batchId,branch:xlBranch}:{branch:xlBranch,from:xlFrom,to:xlTo})});if(!r.ok)throw new Error((await r.json()).error);let url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download=batchId?'ไตยสยาม-ตรวจนำเข้า.xlsx':'ไตยสยาม-บัญชีขาย.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('สร้างไฟล์ Excel แล้ว')}catch(e){xlError=e.message;render()}}
function xlDetail(id){let r=xlState.records.find(r=>r.id===id);modal('บัญชีขาย '+esc(r.date),`<p>${esc(r.branch)} · ${esc(r.source.filename)} ${badge(esc(r.status))}</p><h3>ยอดขายก่อนปรับ ${fmt(r.sales)} บาท</h3>${table(['หัวจ่าย','น้ำมัน','ลิตรขาย','ราคา','ยอดขาย'],r.lines.map(l=>`<tr><td>${esc(l.pump)}${l.split?' (แยกต้นทุน)':''}</td><td>${esc(xlFuelLabel(l.fuel))}</td><td>${fmt(l.liters)}</td><td>${fmt(l.price)}</td><td>${fmt(l.liters*l.price)}</td></tr>`))}<p>${esc(r.note)}</p><p>ประวัติรุ่นก่อนแก้ไข: ${r.versions?.length||0} รุ่น</p><div class="note">หากต้องแก้ไข ให้ส่งออก Excel แก้ช่องกรอก แล้วนำกลับมาเทียบก่อนอัปเดต</div>`)}
function xlManual(){modal('บันทึกยอดขายจริง',`<form onsubmit="event.preventDefault();xlSaveManual(this)"><div class="note"><button type="button" onclick="xlFillExample(this.form)">กรอกข้อมูลตัวอย่าง 1 วัน</button><p>สำหรับลองระบบ · แยกเป็นสาขาทดสอบ · ตรวจแล้วกดบันทึกเอง</p><div id="xlExampleSummary" role="status"></div></div><div class="formgrid">${field('สาขาจริง','realBranch',xlBranch||'TAI SIAM Tachileik','text','required')}${field('วันที่ธุรกิจ','realDate',new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok'}).format(new Date()),'date','required')}</div><p>หัวจ่ายตามรูปแบบ Excel นี้ · กรอกเฉพาะหัวจ่ายที่มีรายการ</p>${['A','B','C','D'].map((p,i)=>`<section class="panel"><h3>หัวจ่าย ${p} · ${i<2?'ดีเซล':i===2?'น้ำมัน 95':'น้ำมัน 91'}</h3><div class="formgrid">${field('มิเตอร์เปิด',p+'open','','number','min="0" step="0.001"')}${field('มิเตอร์ปิด',p+'close','','number','min="0" step="0.001"')}${field('ราคาขาย/ลิตร',p+'price','','number','min="0" step="0.001"')}${field('ต้นทุน/ลิตร (ถ้าทราบ)',p+'cost','','number','min="0" step="0.001"')}</div><details><summary>ส่วนลด ลูกหนี้ และข้อมูลน้ำมัน</summary><div class="formgrid">${[['discount','ส่วนลด (บาท)'],['credit','ขายเชื่อ (บาท)'],['debtPaid','รับชำระหนี้ (บาท)'],['received','รับเข้า (ลิตร)'],['legacyR','วัดจริง (ลิตร)'],['legacyV','เกิน (ลิตร)'],['legacyW','หาย (ลิตร)']].map(([k,n])=>field(n,p+k,'','number','min="0" step="0.01"')).join('')}</div></details></section>`).join('')}${field('หมายเหตุ','realNote')}<div id="xlManualError"></div><button class="primary">บันทึกในสมุดจริง</button></form>`)}
async function xlSaveManual(form){let lines=[];for(let [i,p] of ['A','B','C','D'].entries()){let n=k=>form.elements[p+k].value===''?null:Number(form.elements[p+k].value),opening=n('open'),closing=n('close'),price=n('price');if(opening===null&&closing===null&&price===null)continue;if(opening===null||closing===null||price===null){$('#xlManualError').innerHTML='<div class="note error">กรอกมิเตอร์เปิด ปิด และราคาให้ครบในหัวจ่ายที่ใช้</div>';return}let l={pump:p,fuel:i<2?'ดีเซล':i===2?'95':'91',opening,closing,price,cost:n('cost'),liters:closing-opening};for(let k of ['discount','credit','debtPaid','received','legacyR','legacyV','legacyW'])l[k]=n(k);lines.push(l)}let button=form.querySelector('button.primary');button.disabled=true;try{await xlApi('/manual',{revision:xlState.revision,branch:form.realBranch.value,date:form.realDate.value,note:form.realNote.value,lines});xlBranch=form.realBranch.value.trim();xlFrom='';xlTo='';xlView='ledger';closeModal();await xlLoad();go('reports');toast('บันทึกแล้ว เปิดใหม่ข้อมูลยังอยู่')}catch(e){$('#xlManualError').innerHTML=`<div class="note error">${esc(e.message)} · ค่าที่กรอกยังอยู่</div>`}finally{button.disabled=false}}
exportPreview=function(){if(canAccount())xlExport();else toast('ข้อมูลจริงต้องใช้บทบาทนักบัญชีหรือเจ้าของ')};
const xlNav=simpleNav;simpleNav=function(){return xlNav().replace('<span>รายงาน</span>','<span>Excel · งานบัญชี</span>')};
const xlRender=render;render=function(){xlRender();if(canAccount()&&['reports','import'].includes(route)){document.querySelector('.demo').firstChild.textContent='พื้นที่ Excel จริง · บันทึกเฉพาะเครื่องนี้ · ยังไม่มีบัญชีผู้ใช้จริง ';}else document.querySelector('.demo').firstChild.textContent='ต้นแบบเพื่อออกแบบระบบ · ข้อมูลสมมติ · ไม่เชื่อมข้อมูลจริง ';};

const xlTasks=tasks;tasks=function(){return (canAccount()?`<section class="panel"><h2>Excel และงานบัญชีจริง</h2><p>นำเข้าไฟล์สาขาTAI SIAM Tachileik ตรวจผลต่าง และส่งออกไปทำงานต่อ</p><button class="primary" onclick="go('reports')">เปิดสมุดบัญชีจริง →</button></section>`:'')+xlTasks()};
if(['reports','import'].includes(location.hash.slice(1)))route=location.hash.slice(1);
render();

function xlFillExample(form){
 const date=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok'}).format(new Date());
 let branch='ทดสอบระบบ (ข้อมูลสมมติ)',suffix=2;
 while(xlState?.records.some(r=>r.branch===branch&&r.date===date))branch='ทดสอบระบบ (ข้อมูลสมมติ) '+suffix++;
 form.reset();
 const example={realBranch:branch,realDate:date,Aopen:100000,Aclose:100500,Aprice:32,Acost:29,Adiscount:100,Acredit:2000,AdebtPaid:500,Areceived:1000,AlegacyR:10498,AlegacyV:0,AlegacyW:2,realNote:'ตัวอย่างทดสอบระบบเท่านั้น: หัวจ่าย A ขาย 500 ลิตร × 32 บาท = 16,000 บาทก่อนส่วนลด/ขายเชื่อ; ไม่ใช่รายการธุรกิจจริง'};
 for(const [key,value] of Object.entries(example))form.elements[key].value=value;
 form.querySelector('details').open=true;
 document.querySelector('#xlExampleSummary').textContent='ตัวอย่างหัวจ่าย A · ขาย 500 ลิตร · ยอดขายก่อนปรับ 16,000 บาท · ส่วนลด 100 บาท · ขายเชื่อ 2,000 บาท · วัดจริง 10,498 ลิตร / หาย 2 ลิตร (ไม่หักเป็นบาท)';
 document.querySelector('#xlManualError').textContent='';
}

function xlFuelLabel(value){return {'ดีเซล':'ดีเซล','95':'น้ำมัน 95','91':'น้ำมัน 91'}[value]||value}
function xlFuelCatalog(){return `<section class="panel"><h2>ประเภทน้ำมันตาม Excel</h2><p class="muted">สาขาTAI SIAM Tachileik · อ้างอิงหัวตาราง Diesel / 95 / 91 ในไฟล์ excel-report.xlsx</p><div class="xl-fuel-catalog">${[['ดีเซล','หัวจ่าย A และ B'],['น้ำมัน 95','หัวจ่าย C'],['น้ำมัน 91','หัวจ่าย D']].map(([name,pump])=>`<div><h3>${name}</h3><p>${pump}</p></div>`).join('')}</div><p class="muted">ไฟล์ไม่ระบุเกรดย่อย B7 หรือเบนซิน/แก๊สโซฮอล์ · น้ำมัน 91 ยังไม่ได้ผูกกับถังจริง จึงยังไม่แสดงปริมาณและความจุถัง</p></section>`}
const fuelCatalogTanks=tanksPage;tanksPage=function(){return xlFuelCatalog()+fuelCatalogTanks()};
const fuelCatalogTasks=tasks;tasks=function(){return xlFuelCatalog()+fuelCatalogTasks()};
const fuelCatalogOverview=overview;overview=function(){return xlFuelCatalog()+fuelCatalogOverview()};
render();
